import { readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";

const ROOT = process.cwd();
const SCHEMA_PATH = resolve(ROOT, "supabase/schema.sql");
const SEED_PATH = resolve(ROOT, "supabase/seed.sql");
const OUT_PATH = resolve(ROOT, "supabase/apply-now.sql");

const [schema, seed] = await Promise.all([readFile(SCHEMA_PATH, "utf8"), readFile(SEED_PATH, "utf8")]);

const output = [
  "-- 4IBIB Supabase apply-now script.",
  "-- Generated by scripts/build-supabase-sql.mjs from supabase/schema.sql and supabase/seed.sql.",
  "-- Run this whole file in Supabase SQL Editor.",
  "",
  "-- === Schema, RLS, policies, functions and bootstrap data ===",
  schema.trim(),
  "",
  "-- === Schedule seed generated from supabase/sources/Escala-de-cultos.xlsx ===",
  seed.trim(),
  ""
].join("\n");

await writeFile(OUT_PATH, output);
console.log(`Wrote ${OUT_PATH}`);
